using System.Security.Cryptography;
using System.Text.Json;
using LXMF;
using NomadNet;

namespace NomadNet.Tests;

[Trait("Category", "Unit")]
public sealed class NomadNetConversationImageTests
{
    [Fact]
    public void ActualPrimaryImageExtractionVectorsDistinguishImageFieldsFromOrdinaryNames()
    {
        // Generated by executing primary 1.4.4 f6b56044b42f6ca08dc99b3ecb9d965a8eb5edb2.
        // The generator/fixture records actual API methods and both primary source SHA-256 values.
        using var fixture = Fixture();
        Assert.Equal("f6b56044b42f6ca08dc99b3ecb9d965a8eb5edb2", fixture.RootElement.GetProperty("commit").GetString());
        foreach (var item in fixture.RootElement.GetProperty("vectors").EnumerateArray())
        {
            var fields = new Dictionary<object, object?>();
            var files = item.GetProperty("files").EnumerateArray().Select(file =>
                (object?)new object?[] { file.GetProperty("name").GetString(),
                    Convert.FromBase64String(file.GetProperty("bytes").GetString()!) }).ToArray();
            if (files.Length > 0) fields[LxmField.FileAttachments] = files;
            if (item.GetProperty("imagePresent").GetBoolean())
            {
                var data = item.GetProperty("imageBytes");
                fields[LxmField.Image] = item.GetProperty("invalidPair").GetBoolean()
                    ? new object?[] { "png", "not bytes" }
                    : item.GetProperty("imageFormat").ValueKind == JsonValueKind.String
                        ? new object?[] { item.GetProperty("imageFormat").GetString(), Convert.FromBase64String(data.GetString()!) }
                        : Convert.FromBase64String(data.GetString() ?? "");
            }
            var actual = NomadNetAttachments.Extract(fields);
            var expected = item.GetProperty("attachments").EnumerateArray().ToArray();
            Assert.Equal(expected.Length, actual.Count);
            for (var index = 0; index < actual.Count; index++)
            {
                Assert.Equal(expected[index].GetProperty("name").GetString(), actual[index].Name);
                Assert.Equal(expected[index].GetProperty("size").GetInt32(), actual[index].Data.Length);
                Assert.Equal(expected[index].GetProperty("sha256").GetString(), Convert.ToHexStringLower(SHA256.HashData(actual[index].Data)));
            }
            var expectedImage = item.GetProperty("imageBytes").ValueKind == JsonValueKind.String &&
                item.GetProperty("imageBytes").GetString()!.Length > 0;
            Assert.Equal(expectedImage ? files.Length : (int?)null, NomadNetAttachments.ImageIndex(fields));
        }
    }

    [Fact]
    public async Task NeverRefusesExplicitLoadAndManualDoesNotDecodeUntilRequested()
    {
        var calls = 0;
        await using var images = new NomadNetConversationImages((_, _) => { calls++; return Task.FromResult("@@"); });
        await images.ShowAsync([Message(1)], NomadNetImageLoading.Never);
        await images.ShowAsync([Message(1)], NomadNetImageLoading.Manual);
        Assert.Equal(0, calls);
        await Assert.ThrowsAsync<InvalidOperationException>(() => images.ShowAsync([Message(1)], NomadNetImageLoading.Never, explicitLoad: true));
        await images.ShowAsync([Message(1)], NomadNetImageLoading.Manual, explicitLoad: true);
        await images.Completion;
        Assert.Equal(1, calls);
        Assert.Single(images.Previews);
        await images.ShowAsync([Message(1)], NomadNetImageLoading.Never);
        Assert.Empty(images.Previews);
    }

    [Theory]
    [InlineData(NomadNetImageLoading.Auto)]
    [InlineData(NomadNetImageLoading.Always)]
    public async Task LocalAutoAndAlwaysDecodeOnceUntilExplicitReload(NomadNetImageLoading mode)
    {
        var calls = 0;
        await using var images = new NomadNetConversationImages((_, _) => { calls++; return Task.FromResult("@@"); });
        await images.ShowAsync([Message(1)], mode);
        await images.Completion;
        await images.ShowAsync([Message(1)], mode);
        await images.Completion;
        Assert.Equal(1, calls);
        await images.ShowAsync([Message(1)], mode, explicitLoad: true, reload: true);
        await images.Completion;
        Assert.Equal(2, calls);
    }

    [Fact]
    public async Task FailedConvertersAndThrowingObserversDoNotDisableOtherImagesOrCoreWithoutObservers()
    {
        var reports = new List<string>();
        await using var images = new NomadNetConversationImages((message, _) =>
            message.Id == Message(2).Id ? Task.FromException<string>(new IOException("fixture converter failed")) : Task.FromResult("@@"));
        images.Log = report => reports.Add(report);
        images.Changed += (_, _) => throw new IOException("fixture observer failed");
        var healthy = 0;
        images.Changed += (_, _) => healthy++;
        await images.ShowAsync([Message(1), Message(2)], NomadNetImageLoading.Auto);
        await images.Completion;
        Assert.Single(images.Previews);
        Assert.Equal(1, healthy);
        Assert.Contains(reports, report => report.Contains("converter failed") && report.Contains(Message(2).Id));
        Assert.Contains(reports, report => report.Contains("observer failed") && report.Contains(Message(1).Id));
        await using var withoutObservers = new NomadNetConversationImages((_, _) => Task.FromResult("@@"));
        await withoutObservers.ShowAsync([Message(1)], NomadNetImageLoading.Auto);
        await withoutObservers.Completion;
        Assert.Single(withoutObservers.Previews);
        images.Log = _ => throw new IOException("fixture log failed");
        await images.ShowAsync([Message(2)], NomadNetImageLoading.Auto, reload: true);
        await images.Completion;
    }

    [Theory]
    [InlineData("\u001b[0m")]
    [InlineData("\r")]
    public async Task UntrustedPreviewControlsAreRejected(string preview)
    {
        await using var images = new NomadNetConversationImages((_, _) => Task.FromResult(preview));
        await images.ShowAsync([Message(1)], NomadNetImageLoading.Auto);
        await images.Completion;
        Assert.Empty(images.Previews);
    }

    [Fact]
    public async Task CancellationNewViewAndConcurrentDisposalJoinTheOwnedDecoder()
    {
        var started = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        var ended = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        var changes = 0;
        var images = new NomadNetConversationImages(async (_, token) =>
        {
            started.TrySetResult();
            try { await Task.Delay(Timeout.InfiniteTimeSpan, token); return "@@"; }
            finally { ended.TrySetResult(); }
        });
        images.Changed += (_, _) => changes++;
        await images.ShowAsync([Message(1)], NomadNetImageLoading.Auto);
        await started.Task.WaitAsync(TimeSpan.FromSeconds(5));
        await images.ShowAsync([], NomadNetImageLoading.Never);
        Assert.True(ended.Task.IsCompleted);
        Assert.Equal(0, changes);
        await Task.WhenAll(images.DisposeAsync().AsTask(), images.DisposeAsync().AsTask());
        await Assert.ThrowsAsync<ObjectDisposedException>(() => images.ShowAsync([], NomadNetImageLoading.Auto));
    }

    [Fact]
    public async Task OnlyTheLatestThirtyTwoImagesAreRetainedAndCallerCancellationStopsWork()
    {
        var calls = 0;
        await using var images = new NomadNetConversationImages((_, _) => { calls++; return Task.FromResult("@@"); });
        await images.ShowAsync(Enumerable.Range(0, 40).Select(Message).ToArray(), NomadNetImageLoading.Auto);
        await images.Completion;
        Assert.Equal(32, calls);
        Assert.Equal(32, images.Previews.Count);
        Assert.DoesNotContain(Message(0).Id, images.Previews.Keys);
        using var canceled = new CancellationTokenSource();
        canceled.Cancel();
        await Assert.ThrowsAnyAsync<OperationCanceledException>(() => images.ShowAsync([], NomadNetImageLoading.Auto, cancellationToken: canceled.Token));
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public async Task ActiveDecodeIsJoinedByCallerCancellationOrDisposal(bool dispose)
    {
        using var stop = new CancellationTokenSource();
        var started = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        var ended = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        await using var images = new NomadNetConversationImages(async (_, token) =>
        {
            started.TrySetResult();
            try { await Task.Delay(Timeout.InfiniteTimeSpan, token); return "@@"; }
            finally { ended.TrySetResult(); }
        });
        await images.ShowAsync([Message(1)], NomadNetImageLoading.Auto, cancellationToken: stop.Token);
        await started.Task.WaitAsync(TimeSpan.FromSeconds(5));
        if (dispose) await Task.WhenAll(images.DisposeAsync().AsTask(), images.DisposeAsync().AsTask());
        else { stop.Cancel(); await images.Completion; }
        Assert.True(ended.Task.IsCompleted);
        Assert.Empty(images.Previews);
    }

    [Fact]
    public async Task OversizedPreviewAndViewAreExplicitFailures()
    {
        await using var images = new NomadNetConversationImages((_, _) => Task.FromResult(new string('@', 65537)));
        await images.ShowAsync([Message(1)], NomadNetImageLoading.Auto);
        await images.Completion;
        Assert.Empty(images.Previews);
        await Assert.ThrowsAsync<InvalidDataException>(() => images.ShowAsync(
            Enumerable.Repeat(Message(1), NomadNetStore.MaximumMessages + 1).ToArray(), NomadNetImageLoading.Auto));
    }

    internal static NomadNetMessage Message(int index) => new(index.ToString("x64"), new string('a', 32), "inbound",
        DateTimeOffset.UnixEpoch.AddSeconds(index), "", "fixture", "received") { ImageAttachmentIndex = 0 };
    internal static JsonDocument Fixture() => JsonDocument.Parse(typeof(NomadNetConversationImageTests).Assembly
        .GetManifestResourceStream("NomadNet.Tests.NomadNetConversationImageVectors.json")!);
}

[Trait("Category", "Integration")]
public sealed class NomadNetConversationImageStorageTests
{
    [ImageBackendFact]
    public async Task UntrustedEncodedInputCannotOpenNetworkProtocols()
    {
        using var listener = new System.Net.Sockets.UdpClient(new System.Net.IPEndPoint(System.Net.IPAddress.Loopback, 0));
        var port = ((System.Net.IPEndPoint)listener.Client.LocalEndPoint!).Port;
        var description = System.Text.Encoding.UTF8.GetBytes(
            $"v=0\r\no=- 0 0 IN IP4 127.0.0.1\r\ns=generated public fixture\r\nc=IN IP4 127.0.0.1\r\nt=0 0\r\nm=video {port} RTP/AVP 96\r\na=rtpmap:96 H264/90000\r\n");
        var images = new NomadNetImages(Environment.GetEnvironmentVariable("DOTRETICULUM_NOMADNET_IMAGE_CONVERTER")!);
        var error = await Record.ExceptionAsync(() => images.ConvertAsync(description));
        var message = Assert.IsType<InvalidDataException>(error).Message;
        Assert.True(message.Contains("not on whitelist", StringComparison.OrdinalIgnoreCase), message);
        Assert.Equal(0, listener.Available);
    }

    [Fact]
    public async Task OversizedOrMissingChecksumAttachmentsFailBeforeConversion()
    {
        var directory = Root();
        try
        {
            var message = NomadNetConversationImageTests.Message(1);
            await NomadNetAttachments.SaveAsync(directory, message.Id, Fields());
            var path = Path.Combine(directory, "attachments", message.Id, "1.bin");
            await using (var stream = File.OpenWrite(path)) stream.SetLength(NomadNetAttachments.MaximumBytes + 1L);
            await Assert.ThrowsAsync<InvalidDataException>(() => NomadNetAttachments.ReadAsync(directory, message.Id, 1));
            File.Delete(path + ".sha256");
            await Assert.ThrowsAsync<FileNotFoundException>(() => NomadNetAttachments.ReadAsync(directory, message.Id, 1));
        }
        finally { Directory.Delete(directory, recursive: true); }
    }

    [NomadNetFunctionalTests.LinuxFact]
    public async Task AttachmentAndConversionCacheDirectoryLinksAreRejected()
    {
        var directory = Root();
        try
        {
            var message = NomadNetConversationImageTests.Message(1);
            var fields = Fields();
            await NomadNetAttachments.SaveAsync(directory, message.Id, fields);
            var file = Path.Combine(directory, "attachments", message.Id, "1.bin");
            File.Delete(file);
            var outside = Path.Combine(directory, "outside.bin");
            await File.WriteAllBytesAsync(outside, Assert.IsType<byte[]>(fields[LxmField.Image]));
            File.CreateSymbolicLink(file, outside);
            await Assert.ThrowsAsync<InvalidDataException>(() => NomadNetAttachments.ReadAsync(directory, message.Id, 1));
            var profile = Path.Combine(directory, "profile");
            Directory.CreateDirectory(profile);
            Directory.CreateSymbolicLink(Path.Combine(profile, "storage"), directory);
            var cache = new NomadNetImageCache(profile, new NomadNetImages("missing-fixture-converter"));
            await Assert.ThrowsAsync<InvalidDataException>(() => cache.ConvertAsync(Assert.IsType<byte[]>(fields[LxmField.Image])));
        }
        finally { Directory.Delete(directory, recursive: true); }
    }

    [Fact]
    public async Task TypedImageReferenceAndVerifiedBytesSurviveStoreRestartAndRejectTampering()
    {
        var directory = Root();
        try
        {
            var fields = Fields();
            var message = NomadNetConversationImageTests.Message(1) with { ImageAttachmentIndex = NomadNetAttachments.ImageIndex(fields) };
            Assert.Equal(1, message.ImageAttachmentIndex);
            await NomadNetAttachments.SaveAsync(directory, message.Id, fields);
            var store = await NomadNetStore.OpenAsync(directory);
            await store.SaveMessageAsync(message);
            var restored = Assert.Single(await (await NomadNetStore.OpenAsync(directory)).MessagesAsync());
            Assert.Equal(1, restored.ImageAttachmentIndex);
            Assert.Equal(Assert.IsType<byte[]>(fields[LxmField.Image]), await NomadNetAttachments.ReadAsync(directory, restored.Id, 1));
            await File.WriteAllTextAsync(Path.Combine(directory, "attachments", message.Id, "1.bin"), "tampered");
            await Assert.ThrowsAsync<InvalidDataException>(() => NomadNetAttachments.ReadAsync(directory, message.Id, 1));
            await Assert.ThrowsAsync<InvalidDataException>(() => NomadNetAttachments.ReadAsync(directory, "../outside", 0));
            await Assert.ThrowsAsync<InvalidDataException>(() => NomadNetAttachments.ReadAsync(directory, message.Id, 64));
            using var canceled = new CancellationTokenSource();
            canceled.Cancel();
            await Assert.ThrowsAnyAsync<OperationCanceledException>(() => NomadNetAttachments.ReadAsync(directory, message.Id, 1, canceled.Token));
        }
        finally { Directory.Delete(directory, recursive: true); }
    }

    [ImageBackendFact]
    public async Task RealConverterPreviewReusesPersistentConversionAndRejectsCorruptCacheThenRecovers()
    {
        var directory = Root();
        try
        {
            var converter = Environment.GetEnvironmentVariable("DOTRETICULUM_NOMADNET_IMAGE_CONVERTER")!;
            var images = new NomadNetImages(converter);
            var fields = Fields();
            var message = NomadNetConversationImageTests.Message(1) with { ImageAttachmentIndex = 1 };
            await NomadNetAttachments.SaveAsync(directory, message.Id, fields);
            var cache = new NomadNetImageCache(directory, images);
            var preview = await NomadNetConversationImages.PreviewAsync(directory, message, cache, images);
            Assert.Contains(preview, character => character is '%' or '@');
            Assert.DoesNotContain("\u001b", preview, StringComparison.Ordinal);
            var restored = new NomadNetImageCache(directory, new NomadNetImages("missing-fixture-converter"));
            Assert.Equal(preview, await NomadNetConversationImages.PreviewAsync(directory, message, restored, images));
            var path = Assert.Single(Directory.GetFiles(Path.Combine(directory, "storage", "cache", "conversions"), "*.webp"));
            await File.WriteAllTextAsync(path, "corrupt");
            await Assert.ThrowsAsync<IOException>(() => NomadNetConversationImages.PreviewAsync(directory, message, restored, images));
            Assert.Equal(preview, await NomadNetConversationImages.PreviewAsync(directory, message, cache, images));
            await Assert.ThrowsAsync<IOException>(() => NomadNetConversationImages.PreviewAsync(directory, message, cache,
                new NomadNetImages("missing-fixture-converter")));
        }
        finally { Directory.Delete(directory, recursive: true); }
    }

    private static Dictionary<object, object?> Fields()
    {
        using var fixture = NomadNetConversationImageTests.Fixture();
        var source = Convert.FromBase64String(fixture.RootElement.GetProperty("vectors")[0].GetProperty("imageBytes").GetString()!);
        return new() { [LxmField.FileAttachments] = new object?[] { new object?[] { "image.png", "ordinary file"u8.ToArray() } },
            [LxmField.Image] = source };
    }
    private static string Root()
    {
        var root = Path.GetFullPath(Path.Combine("artifacts", "tests", "nomadnet-conversation-images-" + Guid.NewGuid().ToString("N")));
        Directory.CreateDirectory(root);
        return root;
    }
}
